import type { FallacyQuestionSeed, FallacySeed } from './fallacy-types';
import type { LessonIllustrationEntry } from './illustrations';

const q = (scenario: string, prompt: string, options: [[string, string], [string, string], [string, string]], answer: 0 | 1 | 2): FallacyQuestionSeed => ({
  scenario, prompt, options: options.map(([text, feedback]) => ({ text, feedback })) as FallacyQuestionSeed['options'], answer,
});
const section = (title: string, body: string, example: string, takeaway: string) => ({ title, body, example, takeaway });
const puzzle = (scenario: string, reason: string, conclusion: string, step: string, repair: string, explanation: string): FallacySeed['puzzle'] => ({
  scenario, prompt: 'Reconstrueer de redenering: onderscheid de gegeven reden, het besluit, de ontbrekende rechtvaardiging en een gericht herstel.',
  categories: ['Genoemde reden', 'Conclusie', 'Ongeoorloofde stap', 'Gericht herstel'],
  cards: [{ text: reason, category: 0 }, { text: conclusion, category: 1 }, { text: step, category: 2 }, { text: repair, category: 3 }], explanation,
});
type PictureCase = { reason: string; step: string; conclusion: string; caption: string };
const picture = (title: string, flawed: PictureCase, repaired: PictureCase): LessonIllustrationEntry => ({
  title, invitation: 'Vergelijk de twee kaarten. Klik een uitspraak aan en volg daarna de benoemde denkstap.',
  variants: [flawed, repaired].map((item, index) => ({
    id: index === 0 ? 'flawed' : 'repaired', label: index === 0 ? 'Onvoldoende steun' : 'Gericht herstel', caption: item.caption,
    data: { family: 'flow', rows: [['r', 'w'], ['c']], nodes: [
      { id: 'r', label: 'Reden', text: item.reason, tone: 'blue' },
      { id: 'w', label: index === 0 ? 'Verzwegen aanname' : 'Expliciete verbinding', text: item.step, tone: index === 0 ? 'orange' : 'purple' },
      { id: 'c', label: 'Conclusie', text: item.conclusion, tone: 'green' },
    ], edges: [{ from: 'r', to: 'c', label: 'aangevoerde reden', kind: 'support' }, { from: 'w', to: 'c', label: 'aangenomen verbinding', kind: 'authorize' }],
    legend: 'Reden en aangenomen verbinding staan naast elkaar. De reden bewijst de verbinding niet; de kaart toont hoe zij voor de conclusie worden gebruikt.',
    },
  })),
});

